# Terraform Module for S3 + RDS + IAM

Here's a production-ready Terraform module implementation supporting dev/prod environments via `tfvars` files and workspaces.

## Directory Structure

```
terraform/
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
└── terraform.tf
```

## Module: S3 (`modules/s3/main.tf`)

```hcl
resource "aws_s3_bucket" "app_bucket" {
  bucket = var.bucket_name

  tags = merge(
    var.tags,
    {
      Name = var.bucket_name
    }
  )
}

# Block all public access
resource "aws_s3_bucket_public_access_block" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Enable versioning
resource "aws_s3_bucket_versioning" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption (KMS or AES-256)
resource "aws_s3_bucket_server_side_encryption_configuration" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm      = var.use_kms ? "aws:kms" : "AES256"
      kms_master_key_id  = var.use_kms ? var.kms_key_id : null
    }
    bucket_key_enabled = true
  }
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_bucket" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.app_bucket]
  bucket     = aws_s3_bucket.app_bucket.id
  role       = aws_iam_role.replication_role[0].arn

  rule {
    status = "Enabled"

    destination {
      bucket            = aws_s3_bucket.replica_bucket[0].arn
      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
      metrics {
        status = "Enabled"
        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

resource "aws_s3_bucket" "replica_bucket" {
  count  = var.enable_replication ? 1 : 0
  bucket = "${var.bucket_name}-replica-${var.replica_region}"

  tags = merge(
    var.tags,
    {
      Name = "${var.bucket_name}-replica"
    }
  )
}

resource "aws_s3_bucket_versioning" "replica_bucket" {
  count  = var.enable_replication ? 1 : 0
  bucket = aws_s3_bucket.replica_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "replication_role" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication_policy" {
  count = var.enable_replication ? 1 : 0
  name  = "${var.bucket_name}-replication-policy"
  role  = aws_iam_role.replication_role[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_bucket.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl"
        ]
        Resource = "${aws_s3_bucket.app_bucket.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete"
        ]
        Resource = "${aws_s3_bucket.replica_bucket[0].arn}/*"
      }
    ]
  })
}
```

### S3 Variables (`modules/s3/variables.tf`)

```hcl
variable "bucket_name" {
  type        = string
  description = "Name of the S3 bucket (must be globally unique)"
}

variable "use_kms" {
  type        = bool
  default     = false
  description = "Use KMS encryption instead of AES-256"
}

variable "kms_key_id" {
  type        = string
  default     = null
  description = "KMS key ARN for encryption (required if use_kms is true)"
}

variable "enable_replication" {
  type        = bool
  default     = false
  description = "Enable cross-region replication (prod only)"
}

variable "replica_region" {
  type        = string
  default     = "us-west-2"
  description = "Region for replica bucket"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to resources"
}
```

### S3 Outputs (`modules/s3/outputs.tf`)

```hcl
output "bucket_id" {
  value       = aws_s3_bucket.app_bucket.id
  description = "S3 bucket ID"
}

output "bucket_arn" {
  value       = aws_s3_bucket.app_bucket.arn
  description = "S3 bucket ARN"
}

output "replica_bucket_id" {
  value       = try(aws_s3_bucket.replica_bucket[0].id, null)
  description = "Replica bucket ID (prod only)"
}
```

