## Module: RDS (`modules/rds/main.tf`)

```hcl
resource "aws_db_subnet_group" "postgres" {
  name       = "${var.instance_identifier}-subnet-group"
  subnet_ids = var.db_subnet_ids

  tags = merge(
    var.tags,
    {
      Name = "${var.instance_identifier}-subnet-group"
    }
  )
}

resource "aws_security_group" "rds" {
  name        = "${var.instance_identifier}-sg"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = var.allowed_security_groups
    description     = "PostgreSQL from app security group"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound"
  }

  tags = merge(
    var.tags,
    {
      Name = "${var.instance_identifier}-sg"
    }
  )
}

resource "random_password" "db_password" {
  length  = 32
  special = true

  lifecycle {
    ignore_changes = all
  }
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.instance_identifier}-db-password"
  recovery_window_in_days = 7

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id      = aws_secretsmanager_secret.db_password.id
  secret_string  = random_password.db_password.result
}

resource "aws_db_instance" "postgres" {
  identifier     = var.instance_identifier
  engine         = "postgres"
  engine_version = var.postgres_version

  instance_class   = var.instance_class
  allocated_storage = var.allocated_storage

  db_name  = var.database_name
  username = "postgres"
  password = random_password.db_password.result

  # Networking
  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false

  # High Availability & Backup
  multi_az               = var.multi_az
  backup_retention_period = var.backup_retention_days
  backup_window          = "03:00-04:00"
  maintenance_window     = "sun:04:00-sun:05:00"

  # Encryption
  storage_encrypted      = true
  kms_key_id            = var.kms_key_id

  # Protection
  deletion_protection = true
  skip_final_snapshot = false
  final_snapshot_identifier = "${var.instance_identifier}-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"

  # Monitoring
  enabled_cloudwatch_logs_exports = ["postgresql"]
  performance_insights_enabled     = var.multi_az ? true : false
  performance_insights_retention_period = var.multi_az ? 7 : null

  # Parameters
  parameter_group_name = aws_db_parameter_group.postgres.name
  copy_tags_to_snapshot = true

  depends_on = [aws_secretsmanager_secret_version.db_password]

  tags = merge(
    var.tags,
    {
      Name = var.instance_identifier
    }
  )
}

resource "aws_db_parameter_group" "postgres" {
  family = "postgres${split(".", var.postgres_version)[0]}"
  name   = "${var.instance_identifier}-params"

  parameter {
    name  = "log_statement"
    value = "all"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  tags = var.tags
}

resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${var.instance_identifier}-connection-string"
  recovery_window_in_days = 7

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id
  secret_string = jsonencode({
    host     = aws_db_instance.postgres.endpoint
    port     = 5432
    database = var.database_name
    username = "postgres"
    password = random_password.db_password.result
  })
}
```

### RDS Variables (`modules/rds/variables.tf`)

```hcl
variable "instance_identifier" {
  type        = string
  description = "RDS instance identifier"
}

variable "postgres_version" {
  type        = string
  default     = "15.4"
  description = "PostgreSQL version"
}

variable "instance_class" {
  type        = string
  description = "RDS instance class (e.g., db.t3.micro, db.t3.medium)"
}

variable "allocated_storage" {
  type        = number
  default     = 20
  description = "Allocated storage in GB"
}

variable "database_name" {
  type        = string
  description = "Default database name"
}

variable "multi_az" {
  type        = bool
  default     = false
  description = "Enable Multi-AZ deployment"
}

variable "backup_retention_days" {
  type        = number
  default     = 7
  description = "Backup retention period in days"
}

variable "kms_key_id" {
  type        = string
  default     = null
  description = "KMS key ARN for encryption"
}

variable "vpc_id" {
  type        = string
  description = "VPC ID"
}

variable "db_subnet_ids" {
  type        = list(string)
  description = "DB subnet IDs"
}

variable "allowed_security_groups" {
  type        = list(string)
  description = "Security group IDs allowed to connect"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Tags to apply to resources"
}
```

### RDS Outputs (`modules/rds/outputs.tf`)

```hcl
output "endpoint" {
  value       = aws_db_instance.postgres.endpoint
  description = "RDS instance endpoint"
}

output "arn" {
  value       = aws_db_instance.postgres.arn
  description = "RDS instance ARN"
}

output "secret_arn" {
  value       = aws_secretsmanager_secret.db_connection.arn
  description = "Secrets Manager secret ARN for connection string"
}

output "security_group_id" {
  value       = aws_security_group.rds.id
  description = "RDS security group ID"
}
```

