## Module: IAM (`modules/iam/main.tf`)

```hcl
# Service account role
resource "aws_iam_role" "service_account" {
  name               = "${var.role_name}-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = var.tags
}

# OIDC trust (prod) or direct service account (dev)
data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [var.oidc_provider_arn != null ? var.oidc_provider_arn : aws_iam_user.service_account[0].arn]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

# Dev: IAM user with programmatic access
resource "aws_iam_user" "service_account" {
  count = var.oidc_provider_arn == null ? 1 : 0
  name  = "${var.role_name}-user"

  tags = var.tags
}

resource "aws_iam_access_key" "service_account" {
  count = var.oidc_provider_arn == null ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}

resource "aws_iam_user_policy_attachment" "service_account" {
  count      = var.oidc_provider_arn == null ? 1 : 0
  user       = aws_iam_user.service_account[0].name
  policy_arn = aws_iam_policy.service_account.arn
}

# Least-privilege policy for S3 and RDS access
data "aws_iam_policy_document" "service_account_policy" {
  # S3 bucket access
  statement {
    actions = [
      "s3:GetObject",
      "s3:ListBucket",
      "s3:GetObjectVersion"
    ]
    resources = [
      var.s3_bucket_arn,
      "${var.s3_bucket_arn}/*"
    ]
  }

  statement {
    actions = ["s3:PutObject"]
    resources = ["${var.s3_bucket_arn}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["private"]
    }
  }

  # RDS connection via Secrets Manager
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = [var.db_secret_arn]
  }

  # RDS connection (no wildcard)
  statement {
    actions = [
      "rds-db:connect"
    ]
    resources = ["arn:aws:rds-db:${var.region}:${var.account_id}:dbuser:*/*"]
  }

  # KMS decrypt for encrypted resources
  dynamic "statement" {
    for_each = var.kms_key_id != null ? [1] : []
    content {
      actions = [
        "kms:Decrypt",
        "kms:DescribeKey"
      ]
      resources = [var.kms_key_id]
    }
  }
}

resource "aws_iam_policy" "service_account" {
  name   = "${var.role_name}-policy"
  policy = data.aws_iam_policy_document.service_account_policy.json
}

resource "aws_iam_role_policy_attachment" "service_account" {
  role       = aws_iam_role.service_account.name
  policy_arn = aws_iam_policy.service_account.arn
}

# Store credentials in Secrets Manager (dev only)
resource "aws_secretsmanager_secret" "iam_credentials" {
  count                   = var.oidc_provider_arn == null ? 1 : 0
  name                    = "${var.role_name}-credentials"
  recovery_window_in_days = 7

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "iam_credentials" {
  count         = var.oidc_provider_arn == null ? 1 : 0
  secret_id     = aws_secretsmanager_secret.iam_credentials[0].id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.service_account[0].id
    secret_access_key = aws_iam_access_key.service_account[0].secret
  })
}
```

