## Root Configuration (`main.tf`)

```hcl
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }

  # Use Terraform Cloud or S3 backend; example below uses S3
  # Uncomment and configure for your setup
  # backend "s3" {
  #   bucket         = "your-terraform-state-bucket"
  #   key            = "infrastructure/terraform.tfstate"
  #   region         = "us-east-1"
  #   encrypt        = true
  #   dynamodb_table = "terraform-locks"
  # }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Environment = local.environment
      Project     = var.project_name
      ManagedBy   = "Terraform"
      Workspace   = terraform.workspace
    }
  }
}

locals {
  environment = terraform.workspace == "default" ? "dev" : terraform.workspace
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  bucket_name       = "${var.project_name}-app-assets-${local.environment}-${data.aws_caller_identity.current.account_id}"
  use_kms           = var.use_kms
  kms_key_id        = var.kms_key_id
  enable_replication = var.enable_s3_replication
  replica_region    = var.replica_region

  tags = merge(
    var.common_tags,
    {
      Name        = "${var.project_name}-bucket-${local.environment}"
      Environment = local.environment
    }
  )
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  instance_identifier = "${var.project_name}-postgres-${local.environment}"
  postgres_version    = var.postgres_version
  instance_class      = var.rds_instance_class
  allocated_storage   = var.rds_allocated_storage
  database_name       = var.database_name
  multi_az            = var.rds_multi_az
  backup_retention_days = var.backup_retention_days
  kms_key_id          = var.kms_key_id

  vpc_id                     = var.vpc_id
  db_subnet_ids              = var.db_subnet_ids
  allowed_security_groups    = [aws_security_group.app_server.id]

  tags = merge(
    var.common_tags,
    {
      Name        = "${var.project_name}-postgres-${local.environment}"
      Environment = local.environment
    }
  )
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  role_name        = "${var.project_name}-service-account-${local.environment}"
  s3_bucket_arn    = module.s3.bucket_arn
  db_secret_arn    = module.rds.secret_arn
  oidc_provider_arn = var.oidc_provider_arn

  region     = var.region
  account_id = data.aws_caller_identity.current.account_id
  kms_key_id = var.kms_key_id

  tags = merge(
    var.common_tags,
    {
      Name        = "${var.project_name}-iam-${local.environment}"
      Environment = local.environment
    }
  )
}

# Application server security group (for RDS access)
resource "aws_security_group" "app_server" {
  name        = "${var.project_name}-app-sg-${local.environment}"
  description = "Security group for application servers"
  vpc_id      = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    var.common_tags,
    {
      Name = "${var.project_name}-app-sg-${local.environment}"
    }
  )
}

data "aws_caller_identity" "current" {}
```

